args.command:
node -e "
import('./src/coupons.js').then(async ({applyCoupon}) => {
  const { priceLines } = await import('./src/pricing.js');
  const p1 = priceLines([{id:'a',unitPriceCents:250,qty:3},{id:'b',unitPriceCents:202,qty:5}]);
  console.log('cart1 subtotal', p1.discountedSubtotal, 'sum of lineNet', p1.lines.reduce((s,l)=>s+l.lineNet,0));
  console.log('cart1 per-line sum', applyCoupon(p1,7).couponDiscount, 'whole-subtotal', Math.floor(p1.discountedSubtotal*7/100+0.5));
  const p2 = priceLines([{id:'a',unitPriceCents:250,qty:3},{id:'b',unitPriceCents:1200,qty:10},{id:'c',unitPriceCents:99,qty:7}]);
  console.log('cart2 subtotal', p2.discountedSubtotal, 'per-line sum', applyCoupon(p2,7).couponDiscount, 'whole-subtotal', Math.floor(p2.discountedSubtotal*7/100+0.5));
});
"

